// Nodo: 1. Pre-procesamiento para YCloud/Meta

const item = $input.item.json;

// --- EXTRAER DATOS DE YCLOUD ---
// YCloud envía el mensaje en diferentes estructuras
const whatsappMsg = item.whatsappInboundMessage || item.payload || item;

// Filtrar solo mensajes de texto
if (!whatsappMsg || !whatsappMsg.from) return null;
if (whatsappMsg.type && whatsappMsg.type !== 'text') {
  // Mensaje no es texto (imagen, audio, etc)
  return [{
    json: {
      esMediaNoSoportado: true,
      clienteTelefonoLimpio: (whatsappMsg.from || '').replace(/\D/g, ''),
      chatIdYCloud: whatsappMsg.from,
      tipoMensaje: whatsappMsg.type || 'unknown'
    }
  }];
}

// --- EXTRACCIÓN DE CAMPOS ---
const clienteTelefonoLimpio = (whatsappMsg.from || '').replace(/\D/g, '');
const mensajeClienteActual = whatsappMsg.text?.body || whatsappMsg.body || '';
const nombrePerfilWA = whatsappMsg.customerProfile?.name || whatsappMsg.profile?.name || null;

// Saludo según hora (Colombia UTC-5)
const now = new Date();
const horaCol = new Date(now.getTime() - 5 * 60 * 60 * 1000).getHours();
let saludo;
if (horaCol < 12) saludo = 'Buenos días';
else if (horaCol < 19) saludo = 'Buenas tardes';
else saludo = 'Buenas noches';

// --- LÓGICA DE MAPEO DE PALABRAS CLAVE (del flujo anterior) ---
let textoBusqueda = mensajeClienteActual.toLowerCase().trim();

const mapeoPalabrasClave = {
  'aguacate': '🥑', 'aguacates': '🥑',
  'fresa': '🍓', 'fresas': '🍓',
  'limon': '🍋', 'limones': '🍋',
  'arandano': '🫐', 'arandanos': '🫐',
  'mango': '🥭', 'naranja': '🍊',
  'manzana': '🍎', 'uva': '🍇',
  'coco': '🥥', 'banano': '🍌',
  'caja': 'caja', 'combo': 'combo'
};

for (const palabra in mapeoPalabrasClave) {
  if (textoBusqueda.includes(palabra)) {
    textoBusqueda = textoBusqueda.replace(new RegExp(palabra, 'g'), mapeoPalabrasClave[palabra]);
  }
}

// --- OUTPUT ---
return [{
  json: {
    clienteTelefonoLimpio,
    chatIdYCloud: whatsappMsg.from,
    mensajeClienteActual,
    textoBusqueda,
    saludo,
    nombrePerfilWA,
    esMediaNoSoportado: false,
    datosOriginalesYCloud: item
  }
}];

