// Preparar respuesta para enviar via YCloud
const respuestaIA = $input.first().json.output || $input.first().json.text || '';
const contexto = $('1. Pre-procesamiento YCloud').first().json;

// Limpiar respuesta para WhatsApp
let mensaje = respuestaIA
  .replace(/\*\*/g, '*') // Markdown bold a WhatsApp bold
  .replace(/\n{3,}/g, '\n\n') // Múltiples saltos a máximo 2
  .trim();

// Fallback si no hay respuesta
if (!mensaje) {
  mensaje = '¡Hola! 🥑 Gracias por escribirnos. ¿En qué puedo ayudarte hoy?';
}

return {
  json: {
    to: contexto.clienteTelefonoLimpio,
    mensaje: mensaje,
    // Metadata para logging
    _metadata: {
      telefono: contexto.clienteTelefonoLimpio,
      mensaje_original: contexto.mensajeClienteActual,
      timestamp: new Date().toISOString()
    }
  }
};
